-- Pure-arithmetic XOR keeps this script portable across Lua 5.2 - 5.4.
local function bxor(a, b)
    local result, place = 0, 1
    while a > 0 or b > 0 do
        local x, y = a % 2, b % 2
        if x ~= y then result = result + place end
        a = (a - x) / 2
        b = (b - y) / 2
        place = place * 2
    end
    return result
end

local function crc32(bytes)
    local crc = 0xFFFFFFFF
    for i = 0, bytes:len() - 1 do
        crc = bxor(crc, bytes:get_index(i))
        for _ = 1, 8 do
            if crc % 2 == 1 then
                crc = bxor(math.floor(crc / 2), 0xEDB88320)
            else
                crc = math.floor(crc / 2)
            end
        end
    end
    return bxor(crc, 0xFFFFFFFF)
end

